## 2. KPI Card — `components/shared/KpiCard.tsx`

Full replacement. The existing card has the right structure but wrong visual weight. These changes:
- White card on off-white page = visible
- Icon gets a colored background bubble not a ring
- Trend indicator gets an arrow + colored bg pill
- Accent stripe is bolder (3px not 1px)
- Value is larger (2rem → 2.25rem)

```tsx
'use client'

import type { LucideIcon } from 'lucide-react'
import { TrendingUp, TrendingDown, Minus } from 'lucide-react'
import { cn } from '@/lib/utils'

interface KpiCardProps {
  label: string
  value: string | number
  subtext: string
  icon: LucideIcon
  trend?: 'up' | 'down' | 'neutral'
  invertTrend?: boolean
  loading?: boolean
  index?: number
  accentColor?: string
}

function TrendBadge({
  trend,
  invertTrend,
  subtext,
}: {
  trend: 'up' | 'down' | 'neutral'
  invertTrend: boolean
  subtext: string
}) {
  const isPositive = invertTrend ? trend === 'down' : trend === 'up'
  const isNeutral = trend === 'neutral'

  if (isNeutral || !subtext) {
    return <p className="mt-2.5 text-xs text-muted-foreground">{subtext}</p>
  }

  return (
    <div className="mt-2.5 flex items-center gap-1.5">
      <span
        className={cn(
          'inline-flex items-center gap-0.5 rounded-full px-1.5 py-0.5 text-[11px] font-semibold',
          isPositive
            ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400'
            : 'bg-red-50 text-red-700 dark:bg-red-500/15 dark:text-red-400',
        )}
      >
        {isPositive ? (
          <TrendingUp className="h-3 w-3" aria-hidden="true" />
        ) : (
          <TrendingDown className="h-3 w-3" aria-hidden="true" />
        )}
        {subtext}
      </span>
    </div>
  )
}

export function KpiCard({
  label,
  value,
  subtext,
  icon: Icon,
  trend = 'neutral',
  invertTrend = false,
  index = 0,
  accentColor = 'oklch(52% 0.24 292)',
}: KpiCardProps) {
  return (
    <div
      className={cn(
        'group relative overflow-hidden rounded-xl bg-card',
        'border border-border',
        'shadow-[var(--shadow-card)]',
        'transition-all duration-150 ease-out',
        'hover:shadow-[var(--shadow-card-hover)] hover:-translate-y-px',
        'animate-fade-in-up p-5',
      )}
      style={{
        animationDelay: `${index * 60}ms`,
        animationFillMode: 'both',
        ['--kpi-accent' as string]: accentColor,
      }}
    >
      {/* Left accent bar (3px, full height) */}
      <div
        className="absolute inset-y-0 left-0 w-[3px] rounded-l-xl"
        style={{ background: `var(--kpi-accent)` }}
        aria-hidden="true"
      />

      {/* Label + icon row */}
      <div className="mb-3 flex items-center justify-between">
        <span className="text-xs font-medium uppercase tracking-[0.06em] text-muted-foreground">
          {label}
        </span>
        <div
          className="flex h-8 w-8 items-center justify-center rounded-lg"
          style={{ background: `color-mix(in oklch, var(--kpi-accent) 12%, transparent)` }}
        >
          <Icon
            className="h-4 w-4"
            style={{ color: `var(--kpi-accent)` }}
            aria-hidden="true"
          />
        </div>
      </div>

      {/* Value */}
      <div className="text-[2.125rem] font-bold tabular-nums leading-none tracking-tight text-foreground">
        {value}
      </div>

      {/* Trend / subtext */}
      <TrendBadge trend={trend} invertTrend={invertTrend} subtext={subtext} />
    </div>
  )
}
```

