## 5. Schedule Timeline — `components/shared/ScheduleTimeline.tsx`

Replace the horizontal scroll timeline with a vertical list. Horizontal timelines look like developer tools. Vertical lists are how every booking app (Calendly, Acuity, Vagaro) presents today's schedule.

```tsx
'use client'

import { CalendarOff, Clock } from 'lucide-react'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'

export interface ScheduleAppointment {
  id: string
  clientName: string
  service: string
  startHour: number
  startMinute: number
  durationMin: number
  artistInitials?: string
  status?: 'confirmed' | 'in-progress' | 'pending'
}

interface ScheduleTimelineProps {
  appointments?: ScheduleAppointment[]
  loading?: boolean
}

function formatTime(hour: number, minute: number): string {
  const h = hour > 12 ? hour - 12 : hour === 0 ? 12 : hour
  const m = minute.toString().padStart(2, '0')
  const period = hour >= 12 ? 'pm' : 'am'
  return `${h}:${m} ${period}`
}

function formatEndTime(startHour: number, startMinute: number, durationMin: number): string {
  const totalMinutes = startHour * 60 + startMinute + durationMin
  return formatTime(Math.floor(totalMinutes / 60) % 24, totalMinutes % 60)
}

const STATUS_CONFIG: Record<
  NonNullable<ScheduleAppointment['status']>,
  { dot: string; label: string; bg: string }
> = {
  confirmed: {
    dot: 'bg-[var(--color-status-confirmed)]',
    label: 'Confirmed',
    bg: 'bg-[color-mix(in_oklch,var(--color-status-confirmed)_8%,transparent)]',
  },
  'in-progress': {
    dot: 'bg-[var(--color-status-in-progress)]',
    label: 'In progress',
    bg: 'bg-[color-mix(in_oklch,var(--color-status-in-progress)_8%,transparent)]',
  },
  pending: {
    dot: 'bg-[var(--color-status-pending)]',
    label: 'Pending',
    bg: 'bg-[color-mix(in_oklch,var(--color-status-pending)_8%,transparent)]',
  },
}

function AppointmentRow({ appt }: { appt: ScheduleAppointment }) {
  const status = appt.status ?? 'confirmed'
  const config = STATUS_CONFIG[status]
  const startLabel = formatTime(appt.startHour, appt.startMinute)
  const endLabel = formatEndTime(appt.startHour, appt.startMinute, appt.durationMin)

  return (
    <li className="group flex items-center gap-4 rounded-lg px-3 py-3 transition-colors hover:bg-muted/40">
      {/* Time column */}
      <div className="w-[4.5rem] shrink-0 text-right">
        <p className="text-[13px] font-semibold tabular-nums text-foreground">{startLabel}</p>
        <p className="text-[11px] tabular-nums text-muted-foreground">{endLabel}</p>
      </div>

      {/* Connector dot + line */}
      <div className="relative flex w-4 shrink-0 flex-col items-center self-stretch">
        <span className={cn('mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full', config.dot)} aria-hidden="true" />
        <span className="my-0.5 flex-1 w-px bg-border/60" aria-hidden="true" />
      </div>

      {/* Content */}
      <div
        className={cn(
          'flex flex-1 items-center justify-between gap-3 rounded-lg border border-border/60 px-3.5 py-2.5',
          config.bg,
        )}
      >
        <div className="min-w-0">
          <p className="truncate text-sm font-semibold text-foreground">{appt.clientName}</p>
          <p className="truncate text-xs text-muted-foreground">{appt.service}</p>
        </div>
        <div className="flex shrink-0 items-center gap-2.5">
          {appt.artistInitials && (
            <div className="flex h-6 w-6 items-center justify-center rounded-full bg-primary/15 text-[10px] font-bold text-primary">
              {appt.artistInitials}
            </div>
          )}
          <div className="flex items-center gap-1 text-[11px] text-muted-foreground">
            <Clock className="h-3 w-3" aria-hidden="true" />
            {appt.durationMin}m
          </div>
        </div>
      </div>
    </li>
  )
}

